package main

import (
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
)

// The linter version is named twice: CI installs one, and the Makefile tells a
// contributor which to install. A newer local binary passes on rules the CI one
// reports, and an older one reports rules CI does not have — either way `make
// lint` says the work is fine and the push disagrees, naming a rule the local
// binary never mentioned. Two places holding the same fact is the shape this
// service keeps finding, so the two are compared here.
func TestLinterVersionIsTheSameLocallyAndInCI(t *testing.T) {
	root := filepath.Join("..", "..")
	read := func(name string) string {
		t.Helper()
		content, err := os.ReadFile(filepath.Join(root, name))
		if err != nil {
			t.Fatal(err)
		}
		return string(content)
	}

	makefile := regexp.MustCompile(`(?m)^GOLANGCI_VERSION\s*=\s*(v[\d.]+)\s*$`).
		FindStringSubmatch(read("Makefile"))
	if makefile == nil {
		t.Fatal("the Makefile no longer pins GOLANGCI_VERSION, so nothing tells a contributor which linter CI uses")
	}
	workflow := regexp.MustCompile(`golangci-lint-action@[^\n]*\n(?:.*\n)?\s*with:\s*\n\s*version:\s*(v[\d.]+)`).
		FindStringSubmatch(read(filepath.Join(".github", "workflows", "ci.yaml")))
	if workflow == nil {
		t.Fatal("CI no longer pins a golangci-lint version, so the Makefile's pin cannot be checked against it")
	}

	if makefile[1] != workflow[1] {
		t.Errorf("the Makefile installs golangci-lint %s and CI runs %s: `make lint` and the push "+
			"will disagree about which rules apply", makefile[1], workflow[1])
	}
}

// The image's VERSION build argument is passed by `make image` and by the
// release workflow, so its default only applies to a bare `docker build .` —
// and a real version number there goes stale the moment the next release
// lands. It had been sitting at v0.4.1-dev five releases later, which meant an
// image built that way labelled itself, and answered /api/v1/meta with, a
// version that shipped months earlier. For an appliance whose images are
// carried between machines on a disk, that label is how you tell what you have.
//
// So the default must not be able to pass for a release. Comparing it against
// the changelog is the check that says exactly that, and it keeps saying it
// without anyone maintaining a list.
func TestImageVersionDefaultCannotPassForARelease(t *testing.T) {
	root := filepath.Join("..", "..")
	dockerfile, err := os.ReadFile(filepath.Join(root, "Dockerfile"))
	if err != nil {
		t.Fatal(err)
	}
	defaults := regexp.MustCompile(`(?m)^ARG VERSION=(\S+)`).FindAllStringSubmatch(string(dockerfile), -1)
	if len(defaults) == 0 {
		t.Fatal("the Dockerfile no longer declares a VERSION build argument")
	}
	changelog, err := os.ReadFile(filepath.Join(root, "CHANGELOG.md"))
	if err != nil {
		t.Fatal(err)
	}
	released := map[string]bool{}
	for _, match := range regexp.MustCompile(`(?m)^## (v[\d.]+)\s*$`).FindAllStringSubmatch(string(changelog), -1) {
		released[match[1]] = true
	}
	if len(released) == 0 {
		t.Fatal("no released versions were found in the changelog, so nothing is being compared")
	}
	for _, match := range defaults {
		bare := strings.TrimSuffix(match[1], "-dev")
		if released[bare] || released[match[1]] {
			t.Errorf("the Dockerfile defaults VERSION to %s, which names a release: an image built "+
				"without --build-arg VERSION would claim to be one", match[1])
		}
	}
}

// The toolchains are pinned in more than one place: go.mod names the Go
// version, ci.yaml and the release workflow resolve it from there, and the
// Dockerfile names its own base image. Node is pinned in the Dockerfile and in
// both workflows.
//
// They agree today. Nothing keeps them agreeing, and the drift is quiet in the
// direction that matters: raise go.mod's toolchain for a fix in the standard
// library and forget the Dockerfile, and everything is tested on the new Go
// while the binary that ships is still built on the old one. The image is the
// artifact; the tests are not.
func TestToolchainPinsAgreeAcrossTheBuild(t *testing.T) {
	root := filepath.Join("..", "..")
	read := func(name string) string {
		t.Helper()
		content, err := os.ReadFile(filepath.Join(root, name))
		if err != nil {
			t.Fatal(err)
		}
		return string(content)
	}
	dockerfile := read("Dockerfile")

	image := regexp.MustCompile(`FROM golang:(\d+\.\d+\.\d+)`).FindStringSubmatch(dockerfile)
	if image == nil {
		t.Fatal("the Dockerfile no longer builds on a pinned golang image")
	}
	toolchain := regexp.MustCompile(`(?m)^toolchain go(\d+\.\d+\.\d+)`).FindStringSubmatch(read("go.mod"))
	if toolchain == nil {
		t.Fatal("go.mod no longer names a toolchain, so the image has nothing to agree with")
	}
	if image[1] != toolchain[1] {
		t.Errorf("the image builds on Go %s and go.mod names %s: everything is tested on one and "+
			"the binary that ships is built on the other", image[1], toolchain[1])
	}

	node := regexp.MustCompile(`FROM node:(\d+\.\d+\.\d+)`).FindStringSubmatch(dockerfile)
	if node == nil {
		t.Fatal("the Dockerfile no longer builds the console on a pinned node image")
	}
	for _, workflow := range []string{"ci.yaml", "release.yaml"} {
		path := filepath.Join(".github", "workflows", workflow)
		for _, match := range regexp.MustCompile(`node-version:\s*(\d+\.\d+\.\d+)`).
			FindAllStringSubmatch(read(path), -1) {
			if match[1] != node[1] {
				t.Errorf("%s builds the console on Node %s and the image uses %s",
					workflow, match[1], node[1])
			}
		}
	}
}

// The compose files name the image an operator runs, and the release script
// saves the archive as resso:<the version it built>. When the two disagree,
// the documented offline install does the one thing an offline install cannot
// do: docker finds no such tag locally and goes to the network for it. The
// maintenance file is worse - it is what someone locked out of the console is
// told to run, so it fails at the moment there is no other way in.
//
// Naming the newest release is what keeps a freshly loaded archive runnable by
// the recipe in the README. Pinning it by hand is how it drifted: both files
// sat on the version they were written for while nine releases went by.
func TestComposeFilesRunTheReleaseThisTreeDescribes(t *testing.T) {
	root := filepath.Join("..", "..")
	changelog, err := os.ReadFile(filepath.Join(root, "CHANGELOG.md"))
	if err != nil {
		t.Fatal(err)
	}
	newest := regexp.MustCompile(`(?m)^## (v[\d.]+)\s*$`).FindStringSubmatch(string(changelog))
	if newest == nil {
		t.Fatal("no released version was found in the changelog, so nothing is being compared")
	}
	for _, name := range []string{"compose.offline.yaml", "compose.maintenance.yaml"} {
		content, err := os.ReadFile(filepath.Join(root, name))
		if err != nil {
			t.Fatal(err)
		}
		images := regexp.MustCompile(`(?m)^\s+image:\s*(\S+)`).FindAllStringSubmatch(string(content), -1)
		if len(images) == 0 {
			t.Errorf("%s names no image", name)
			continue
		}
		for _, image := range images {
			// Either the tag itself or the default of the variable standing in
			// for it: resso:${RESSO_VERSION:-vX.Y.Z}.
			tag := image[1]
			if fallback := regexp.MustCompile(`\$\{[A-Z_]+:-([^}]+)\}`).FindStringSubmatch(tag); fallback != nil {
				tag = strings.Replace(tag, fallback[0], fallback[1], 1)
			}
			if want := "resso:" + newest[1]; tag != want {
				t.Errorf("%s runs %s, but this tree describes %s: an archive loaded from the "+
					"release is tagged %s, so the documented recipe finds no such image and "+
					"reaches for the network", name, image[1], newest[1], want)
			}
		}
	}
}

// The database the tests run against is named in three places: the script that
// starts the local services, the service block of the release workflow, and
// the manual recipe in the README. Every merge is gated on the script's
// version, and the last check before an image ships runs the whole backend
// suite on the release workflow's.
//
// They disagreed. The script moved to a newer major and the other two stayed
// on the one they were written for, so a change that behaves differently
// between them passed every merge and was first met at the release - and a
// developer following the README ran their tests against a third position.
// Which major is correct is a decision; having three of them is not.
func TestThePostgresVersionIsTheSameEverywhereItIsNamed(t *testing.T) {
	root := filepath.Join("..", "..")
	pattern := regexp.MustCompile(`postgres:(\S+?)(?:\s|$|>)`)
	found := map[string][]string{}
	for _, name := range []string{
		"scripts/test-services.sh",
		filepath.Join(".github", "workflows", "release.yaml"),
		filepath.Join(".github", "workflows", "ci.yaml"),
		"README.md",
	} {
		content, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(name)))
		if err != nil {
			t.Fatal(err)
		}
		for _, match := range pattern.FindAllStringSubmatch(string(content), -1) {
			// postgres://... is a connection string, not an image.
			if strings.HasPrefix(match[1], "//") {
				continue
			}
			found[match[1]] = append(found[match[1]], name)
		}
	}
	if len(found) == 0 {
		t.Fatal("no PostgreSQL image is named anywhere, so nothing is being compared")
	}
	if len(found) > 1 {
		t.Errorf("the tests run against %d different PostgreSQL images: %v — every merge is gated "+
			"on one and the release on another, so a difference between them is first met "+
			"where there is no time left to meet it", len(found), found)
	}
}

// .env.example is the file the README tells an operator to copy to .env before
// bringing the compose deployment up, so every name in it is an invitation to
// set something. A name compose never reads is an invitation to nothing: the
// value is accepted, no error is raised, and the deployment goes on behaving
// as though it were never written - which is worse than not offering it, since
// the operator now believes they changed it.
func TestEveryOfferedSettingReachesTheDeployment(t *testing.T) {
	root := filepath.Join("..", "..")
	example, err := os.ReadFile(filepath.Join(root, ".env.example"))
	if err != nil {
		t.Fatal(err)
	}
	var compose strings.Builder
	for _, name := range []string{"compose.offline.yaml", "compose.maintenance.yaml"} {
		content, err := os.ReadFile(filepath.Join(root, name))
		if err != nil {
			t.Fatal(err)
		}
		compose.Write(content)
	}
	offered := regexp.MustCompile(`(?m)^#?\s*([A-Z][A-Z0-9_]+)=`).FindAllStringSubmatch(string(example), -1)
	if len(offered) == 0 {
		t.Fatal(".env.example offers no settings, so nothing is being compared")
	}
	for _, match := range offered {
		if !strings.Contains(compose.String(), "${"+match[1]) {
			t.Errorf(".env.example offers %s and no compose file reads it: setting it in .env "+
				"changes nothing and says nothing, so the operator is left believing it took "+
				"effect", match[1])
		}
	}
}

// Dropping a digest key that something still resolves under does not degrade
// anything gracefully: the value simply stops matching. The operations guide
// gets this right and says so in three bullets, the last of which decides the
// timing — client secrets never expire, so the key cannot go until every one
// of them has been rotated.
//
// A shorter telling of the same rule that leaves that out is not a smaller
// version of it, it is a different rule: followed literally, an operator waits
// out the session and token lifetimes, removes the key, and every confidential
// client whose secret predates the change stops authenticating at the token,
// introspection and revocation endpoints at once.
func TestEveryTellingOfTheDigestKeyRuleNamesClientSecrets(t *testing.T) {
	root := filepath.Join("..", "..")
	checked := 0
	for _, name := range []string{"README.md", filepath.Join("docs", "operations.md")} {
		content, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(name)))
		if err != nil {
			t.Fatal(err)
		}
		// A paragraph that says how long to keep a digest key, together with
		// the list and the sentences that follow it: the guide states the rule
		// as a sentence and then names the items in bullets, so reading the
		// paragraph alone would call the complete telling incomplete.
		blocks := strings.Split(string(content), "\n\n")
		for index, block := range blocks {
			if !strings.Contains(block, "Digest Key") || !strings.Contains(block, "유지") {
				continue
			}
			for offset := 1; offset <= 2 && index+offset < len(blocks); offset++ {
				block += "\n\n" + blocks[index+offset]
			}
			checked++
			if !strings.Contains(block, "Client Secret") {
				t.Errorf("%s tells the digest key retention rule without naming Client Secret, which is "+
					"the item that decides when the key can go — every other one expires on its own:\n%s",
					name, block)
			}
		}
	}
	if checked == 0 {
		t.Fatal("no telling of the digest key retention rule was found, so nothing is being compared")
	}
}
